// Returns the factorial of a non-negative integer n
function factorial(n) {
  if (n < 0) {
    throw new Error('Input must be a non-negative integer');
  }
  if (n === 0 || n === 1) {
    return 1;
  }
  return n * factorial(n - 1);
}
